/*
 * The active content database.
 *
 * The imported game data (generated by scripts/import-core.mjs, all books, ~14 MB)
 * lives in public/core.json and is FETCHED at runtime rather than bundled into the
 * JS — at this size, inlining it via `?raw` would bloat the bundle and slow startup.
 * On load we merge the hand-authored seed underneath it: Core is canonical, the seed
 * fills any gaps (so the example character keeps resolving even where Core lacks an
 * exact slug).
 */
import type { ContentDatabase, SourceInfo } from '../rules/types';
import { seedContent } from '../rules/seed';
import { CATALOG_MODE_MAP } from '../rules/modes';
import { loadHomebrewContent, loadHomebrewSources, loadModes, HOMEBREW_TYPES } from './storage';

function merge<T>(base: Record<string, T>, over: Record<string, T>): Record<string, T> {
  return { ...base, ...over };
}

/** Feats deliberately excluded from the app (per user decision) — dropped from content AFTER the merge,
 *  so they never appear in any picker or resolve as a grant. Applied here in the loader rather than in
 *  the data file, so the exclusion survives every core.json regeneration.
 *
 *  The tattoo CHAIN must be excluded together. `arcane-tattoos` was excluded on its own, which left
 *  `ornate-tattoo` (prerequisite "Arcane Tattoos") and, behind it, `virtue-forged-tattoos`
 *  (prerequisite "Ornate Tattoo") in the pickers with a prerequisite that can never be met — the
 *  parent no longer exists in the running database. Both also read "the same school as your Arcane
 *  Tattoos", a school the character can never have chosen. Excluding a feat means excluding whatever
 *  depends on it. */
export const EXCLUDED_FEATS = new Set(['arcane-tattoos', 'ornate-tattoo', 'virtue-forged-tattoos', 'hag-magic']);

/** Collections where an `aon-`-prefixed scrape can shadow an existing record of the same name. */
const DEDUPE_MAPS = ['items', 'feats', 'spells', 'actions', 'vehicles', 'backgrounds', 'heritages', 'deities'] as const;
const dedupeKey = (name: string) => name.toLowerCase().replace(/[^a-z0-9]/g, '');

/**
 * `aon-` duplicates the exact-name match walks straight past, because the scrape spelled the name
 * differently — "Historical Reeanactor" beside "Historical Reenactor".
 *
 * Scanning every `aon-` record for a canonical name within edit distance 2, then scoring the two
 * descriptions by word overlap, found 46 such pairs. 42 of them turned out to ALSO have an
 * exactly-named twin, so the rule above already hid them; listing those here would be 42 lines that
 * do nothing. The four below are the real holes, and all four are BACKGROUNDS — a collection that
 * was missing from DEDUPE_MAPS entirely.
 *
 * Not every near-miss is a duplicate: Minor vs Major Astonishing Ink, Magic Armor vs Magic Armor (+1),
 * the ten scroll ranks, Firearm Ammunition 5 vs 10 rounds, Searing vs Healing Wave and Shield Bash vs
 * Shield Boss all read alike and are distinct records. A similarity threshold alone cannot tell a
 * typo from a grade, which is why this list is curated rather than computed at load.
 *
 * Hidden, never deleted — same reason as the exact-name set: a saved character may already reference
 * one of these ids, and an id that vanishes takes the player's background with it.
 */
export const NEAR_DUPLICATE_IDS = new Set([
  'aon-historical-reeanactor', // -> historical-reenactor
  'aon-post-guard-of-all-trade', // -> post-guard-of-all-trades
  'aon-reclaimed-investigator', // -> reclaimer-investigator
  'aon-wishes-for-riches', // -> wish-for-riches
  // Not an `aon-` scrape, and not a background: TWO imports of the same AoN document (feat-4709)
  // under different names, so the exact-name pass above cannot see them and neither can the `aon-`
  // prefix rule. MEASURED on the live db: `eligibleFeatsForSlot` for a level-1 druid class slot
  // returned 13 options and TWO of them were this feat, and the mirror index holds exactly one druid
  // document under that id. The KEPT id is `animal-empathy`: it is the fully-modelled record of the
  // pair (it carries `actionCost`, `prerequisites` and a source license; the hidden one carries
  // none of the three). ⚠ Do NOT generalise this into a sweep from `npm run scan:dupe-feats` — that
  // scanner finds 40 colliding groups and its own EXEMPT notes record why no blanket rule works.
  'animal-empathy-druid', // -> animal-empathy
]);

/**
 * Ids of `aon-`-prefixed records that DUPLICATE a canonical record of the same name in the same
 * collection. An earlier scrape re-added content the app already had under a different id, so
 * pickers list many entries twice (408 item pairs, 100 actions, 81 feats, 91 Kingmaker rows…).
 *
 * These are HIDDEN FROM LISTS rather than deleted from the database. Deleting them would orphan any
 * saved character that already picked one (characters store raw ids — feats[].featId,
 * inventory[].itemId, spell slots…), and 149 other `aon-` records are the ONLY copy of their content
 * (72 animal companions, 37 vehicles, 14 conditions) so a blanket prefix rule would destroy real
 * data. Collision-only + hide-don't-delete keeps every existing reference resolvable.
 */
export function findDuplicateIds(db: ContentDatabase): Set<string> {
  const dupes = new Set<string>();
  for (const mapName of DEDUPE_MAPS) {
    const map = db[mapName] as unknown as Record<string, { name?: string }> | undefined;
    if (!map) continue;
    const canonical = new Set<string>();
    for (const [id, rec] of Object.entries(map)) {
      if (!rec?.name || id.startsWith('aon-')) continue;
      canonical.add(dedupeKey(rec.name));
    }
    for (const [id, rec] of Object.entries(map)) {
      // Only an `aon-` record that COLLIDES with a canonical twin is a duplicate; an `aon-` record
      // that is the sole copy of its content stays visible.
      if (id.startsWith('aon-') && rec?.name && canonical.has(dedupeKey(rec.name))) dupes.add(id);
    }
  }
  // The curated near-miss set: same content, different spelling, so the exact match above misses it.
  // Guarded on existence so a retired id never hides something that took its place.
  for (const id of NEAR_DUPLICATE_IDS) {
    for (const mapName of DEDUPE_MAPS) {
      if ((db[mapName] as unknown as Record<string, unknown> | undefined)?.[id]) dupes.add(id);
    }
  }
  for (const id of gradeSpellingDuplicates(db)) dupes.add(id);
  return dupes;
}

/** The grade words PF2e puts on an item family, in both spellings. */
const GRADE_WORDS = ['lesser', 'moderate', 'greater', 'major', 'minor', 'true', 'supreme'];

/**
 * "Greater Nail Bomb" and "Nail Bomb (Greater)" — the SAME item under two spellings, so neither the
 * exact-name rule nor the curated near-miss list hides either, and the shop lists both. 180 item
 * pairs were in that state: two importer generations of the same record, and a player searching
 * "nail bomb" got eight rows for four items.
 *
 * The signal is exact rather than fuzzy, which is what makes a computed rule safe here where a
 * similarity threshold would not be (see NEAR_DUPLICATE_IDS on why Minor vs Major Astonishing Ink
 * must not collapse): the two names must be identical once the grade word moves, AND the two records
 * must agree on level AND on price. Grade IS part of the key, so a lesser and a greater never merge.
 *
 * The loser is the "Grade Name" spelling. AoN prints "Name (Grade)", every one of the 180 clean
 * records uses it, and the "Grade Name" half is the older scrape whose description still carries the
 * page furniture ("May contain spoilers from…", a repeated Source/Usage/Bulk line) and covers all
 * grades at once. Note the loser cannot be chosen by that text: descriptions live in a second file
 * that has not loaded when this runs, so the choice is made on the NAME shape, which is in core.json.
 *
 * Hidden, never deleted — a saved character may already carry one in its inventory.
 */
function gradeSpellingDuplicates(db: ContentDatabase): string[] {
  type Priced = { name?: string; level?: number; price?: Record<string, number> };
  const items = db.items as unknown as Record<string, Priced> | undefined;
  if (!items) return [];
  /** In copper, so `{gp: 70000}` and `{pp:0, gp:70000, sp:0, cp:0}` compare equal. */
  const copper = (p: Priced['price']) =>
    (p?.pp ?? 0) * 1000 + (p?.gp ?? 0) * 100 + (p?.sp ?? 0) * 10 + (p?.cp ?? 0);
  /** "Greater Nail Bomb" and "Nail Bomb (Greater)" both key to "nail bomb|greater". */
  const key = (name: string): string | null => {
    let s = name.toLowerCase().replace(/['’]/g, '').trim();
    let grade: string | null = null;
    const paren = /\s*\(([^)]+)\)\s*$/.exec(s);
    if (paren && GRADE_WORDS.includes(paren[1].trim())) {
      grade = paren[1].trim();
      s = s.slice(0, paren.index);
    } else {
      const first = /^([a-z]+)\s+/.exec(s);
      if (first && GRADE_WORDS.includes(first[1])) {
        grade = first[1];
        s = s.slice(first[0].length);
      }
    }
    return grade ? `${s.replace(/[^a-z0-9]+/g, ' ').trim()}|${grade}` : null;
  };
  const byKey = new Map<string, string[]>();
  for (const [id, rec] of Object.entries(items)) {
    if (!rec?.name) continue;
    const k = key(rec.name);
    if (!k) continue;
    const list = byKey.get(k);
    if (list) list.push(id);
    else byKey.set(k, [id]);
  }
  const out: string[] = [];
  for (const ids of byKey.values()) {
    if (ids.length < 2) continue;
    if (new Set(ids.map((i) => items[i].level ?? null)).size !== 1) continue; // different item — leave both
    if (new Set(ids.map((i) => copper(items[i].price))).size !== 1) continue;
    // Keep the "Name (Grade)" spelling; hide the "Grade Name" one.
    const prefixed = ids.filter((i) => !/\)\s*$/.test(items[i].name!));
    if (prefixed.length && prefixed.length < ids.length) out.push(...prefixed);
  }
  return out;
}

/**
 * Ids of item records that are an AoN SUMMARY of a family rather than a thing you can own.
 *
 * Archives of Nethys heads each graded family with a summary row — "Bestial Mutagen" above
 * "(Lesser)", "(Moderate)", "(Greater)" — and the scrape imports it like any other item. The owner's
 * ruling: "the summary of all of the items shouldn't be an option for the characters, it's not a
 * real item so they shouldn't even see that, they should only see the options they can have."
 *
 * Three conditions, all required:
 *   • NO PRICE. The summary carries none; every grade carries its own.
 *   • TWO OR MORE KIN — ids that extend this one. A single twin can be a genuine base item plus one
 *     upgrade; two or more is a family with a summary at its head.
 *   • NO MECHANICAL FIELD. The guard that spares anything the app actually resolves. Energy Robe is
 *     unpriced with four kin and would have been hidden, but it carries `effectChoices` — it IS the
 *     ownable item and its kin are AoN's row per choice. `staff` and `sling` are spared by `damage`.
 *
 * Hidden, not deleted, exactly like the duplicate scrapes above: a character who added one while it
 * was visible keeps resolving it.
 */
const UMBRELLA_MECHANICAL_FIELDS = [
  'passiveEffects', 'effectChoices', 'situational', 'uses', 'spell', 'runes',
  'damage', 'acBonus', 'capacity', 'value', 'heldSpells', 'dynamicSkillBonus', 'spellSlotBonus',
] as const;

/** Summary rows no rule can reach: no price and no kin either, so only the id identifies them. */
const UMBRELLA_EXTRA_IDS = [
  'aon-magical-medals', // AoN's category page for medals; the medals themselves are unrelated ids
];

/**
 * Records the rule catches but must NOT hide, found by auditing all 438 candidates against the
 * pristine AoN mirror. AoN titles a family head "Item N+" and a standalone "Item N"; 436 of the 438
 * carry the `+`, and these four are where the price-and-kin rule and AoN's own marker disagree.
 *
 * The first three are unpriced in our import but priced on AoN, and the app's variants do NOT cover
 * the base — hiding them would delete the base item from the game with nothing left to buy.
 */
const UMBRELLA_KEEP_IDS = new Set([
  // AoN: Item 10, 975 gp. The app has only (Greater) and (Major), so this IS the base spellheart.
  'judgement-thurible',
  // AoN: Item 4, 100 gp, with its own spell list. The app has only (Greater) and (Major).
  'spore-shepherds-staff',
  // AoN: "Item 2" with no `+` — one complete record. Priceless because the Razmiran Priest archetype
  // grants it, not because it is a summary; the Gold/Silver/Porcelain kin are the higher-level masks
  // and there is no iron variant, so this record is the only iron mask there is.
  'razmiri-mask',
  // Not an item and not a summary: AoN relic-86, a Relic Minor Gift mis-imported into `items`. Its
  // kin are *Inspiring Spotlight*, a pure name-prefix collision.
  'inspiring',
]);

export function findUmbrellaIds(items: Record<string, unknown> | undefined): Set<string> {
  const out = new Set<string>();
  if (!items) return out;
  const ids = Object.keys(items);
  const rec = items as Record<string, Record<string, unknown>>;
  const priced = (it: Record<string, unknown>) => {
    const p = it.price as Record<string, number> | undefined;
    return !!p && Object.values(p).some(Boolean);
  };
  const mechanical = (it: Record<string, unknown>) =>
    UMBRELLA_MECHANICAL_FIELDS.some((k) => {
      const v = it[k];
      return v != null && (!Array.isArray(v) || v.length > 0);
    });

  // Sorted once so the kin scan is a bounded walk forward rather than a full pass per id — this runs
  // over ~7,500 items at every content load.
  const sorted = [...ids].sort();
  for (let i = 0; i < sorted.length; i++) {
    const id = sorted[i];
    const it = rec[id];
    if (!it || priced(it) || mechanical(it) || UMBRELLA_KEEP_IDS.has(id)) continue;
    let kin = 0;
    for (let j = i + 1; j < sorted.length && sorted[j].startsWith(id + '-'); j++) kin++;
    if (kin >= 2) out.add(id);
  }
  for (const id of UMBRELLA_EXTRA_IDS) if (rec[id]) out.add(id);
  return out;
}

/** True if `id` is a duplicate scrape that should be omitted from user-facing lists. */
export function isDuplicateId(content: ContentDatabase, id: string): boolean {
  return !!content.duplicateIds?.has(id);
}

/** `Object.values(map)` minus duplicate scrapes — use this for ANY list the user reads or picks
 *  from, so the same entry never appears twice. Direct `content.x[id]` lookups are untouched, so a
 *  character that already references a duplicate still resolves it. */
export function listValues<T>(content: ContentDatabase, map: Record<string, T>): T[] {
  const dupes = content.duplicateIds;
  // Umbrella summaries hide through the same chokepoint as duplicate scrapes — both are records the
  // player should never be offered, and both stay resolvable by direct id lookup.
  const umbrellas = map === (content.items as unknown as Record<string, T>) ? content.umbrellaIds : undefined;
  if (!dupes?.size && !umbrellas?.size) return Object.values(map);
  const out: T[] = [];
  for (const id in map) if (!dupes?.has(id) && !umbrellas?.has(id)) out.push(map[id]);
  return out;
}

function mergeWithSeed(core: Partial<ContentDatabase>): ContentDatabase {
  const c = core as ContentDatabase;
  // Seed → Core → user homebrew, so homebrew entries resolve everywhere core content does.
  const hb = loadHomebrewContent();
  // Tag each homebrew entry's source.book with its Source's name, so the per-character Sources filter
  // (applySources) governs it: a homebrew Source is off by default and opt-in via Setup → Sources.
  const hbSources = loadHomebrewSources();
  for (const type of HOMEBREW_TYPES) {
    for (const entry of Object.values(hb[type]) as unknown as { homebrewSourceId?: string; source?: SourceInfo }[]) {
      const name = entry.homebrewSourceId ? hbSources[entry.homebrewSourceId]?.name : undefined;
      entry.source = { ...(entry.source ?? {}), license: 'homebrew', ...(name ? { book: name } : {}) };
    }
  }
  const db: ContentDatabase = {
    ancestries: merge(merge(seedContent.ancestries, c.ancestries ?? {}), hb.ancestries),
    heritages: merge(merge(seedContent.heritages, c.heritages ?? {}), hb.heritages),
    backgrounds: merge(merge(seedContent.backgrounds, c.backgrounds ?? {}), hb.backgrounds),
    classes: merge(seedContent.classes, c.classes ?? {}),
    classFeatures: merge(seedContent.classFeatures, c.classFeatures ?? {}),
    feats: merge(merge(seedContent.feats, c.feats ?? {}), hb.feats),
    spells: merge(merge(seedContent.spells, c.spells ?? {}), hb.spells),
    items: merge(merge(seedContent.items, c.items ?? {}), hb.items),
    deities: merge(seedContent.deities, c.deities ?? {}),
    languages: merge(seedContent.languages, c.languages ?? {}),
    animalCompanions: merge(seedContent.animalCompanions, c.animalCompanions ?? {}),
    familiarAbilities: merge(seedContent.familiarAbilities, c.familiarAbilities ?? {}),
    companionSpecializations: merge(seedContent.companionSpecializations ?? {}, c.companionSpecializations ?? {}),
    companionAdvanced: merge(seedContent.companionAdvanced ?? {}, c.companionAdvanced ?? {}),
    specificFamiliars: merge(seedContent.specificFamiliars ?? {}, c.specificFamiliars ?? {}),
    followers: merge(seedContent.followers ?? {}, c.followers ?? {}),
    pets: merge(seedContent.pets ?? {}, c.pets ?? {}),
    services: merge(seedContent.services ?? {}, c.services ?? {}),
    vehicles: merge(seedContent.vehicles ?? {}, c.vehicles ?? {}),
    siegeWeapons: merge(seedContent.siegeWeapons ?? {}, c.siegeWeapons ?? {}),
    conditions: merge(seedContent.conditions, c.conditions ?? {}),
    actions: merge(merge(seedContent.actions, c.actions ?? {}), hb.actions),
    // Built-in mode catalog, then core's item modes (one per consumable that changes you for a
    // stated span of time — hidden from the Modes panel, reached only by Using the item), then the
    // user's saved modes on top.
    modes: merge(merge(CATALOG_MODE_MAP, c.modes ?? {}), loadModes()),
    stances: merge(seedContent.stances ?? {}, c.stances ?? {}),
    runes: c.runes ?? {},
  };
  for (const id of EXCLUDED_FEATS) delete db.feats[id];
  // Carry over any EXTRA buckets core ships that aren't in the explicit list above — the glossary/reference
  // buckets (rules, trait, source, skill, domain, class sub-options, …) whose only job is to let a
  // description cross-link resolve and open. They have no seed/homebrew layer, so a straight copy is right.
  const extra = db as unknown as Record<string, unknown>;
  const coreRec = c as unknown as Record<string, unknown>;
  for (const k in coreRec) if (!(k in db)) extra[k] = coreRec[k];
  // Computed last, so it sees seed + core + homebrew (homebrew never uses the `aon-` prefix, but a
  // homebrew entry CAN be the canonical twin that unmasks a duplicate).
  db.duplicateIds = findDuplicateIds(db);
  db.umbrellaIds = findUmbrellaIds(db.items as unknown as Record<string, unknown>);
  return db;
}

let cached: ContentDatabase | null = null;
let cachedCore: Partial<ContentDatabase> = {};
let pending: Promise<ContentDatabase> | null = null;

/** Re-merge seed + core + the current homebrew (re-read from storage) without re-fetching core.json.
 *  Call after the user edits homebrew so the live content DB reflects it immediately. */
export function rebuildContent(): ContentDatabase {
  cached = mergeWithSeed(cachedCore);
  return cached;
}

/** Set once the description file has been merged in, so a late subscriber is told immediately. */
let descriptionsLoaded = false;

const descListeners = new Set<(db: ContentDatabase) => void>();
/** Subscribe to "descriptions have arrived". Returns an unsubscribe. */
export function onDescriptionsLoaded(fn: (db: ContentDatabase) => void): () => void {
  // Fire IMMEDIATELY when they have already arrived. main.tsx prefetches content before React mounts,
  // so the descriptions usually land BEFORE App subscribes — a plain subscription misses the
  // notification entirely and every description stays blank until something else forces a render.
  if (descriptionsLoaded && cached) fn(cached);
  descListeners.add(fn);
  return () => {
    descListeners.delete(fn);
  };
}

let descPending: Promise<void> | null = null;
/**
 * Fetch public/core-descriptions.json and write each description back onto the record it belongs to.
 *
 * Writes each description onto the RAW core record and re-merges, so subscribers get a database with
 * a NEW identity. That is the reason this split is a small change instead of a large one: 189 places
 * read `record.description` synchronously and every one keeps working — the text simply appears a
 * beat later. A failure here costs description text and nothing else, so it never rejects.
 */
export function loadDescriptions(): Promise<void> {
  descPending ??= (async () => {
    try {
      const res = await fetch(`${import.meta.env.BASE_URL}core-descriptions.json`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const byBucket = (await res.json()) as Record<string, Record<string, { d?: string; r?: unknown }>>;
      // Write into the RAW core, then rebuild. Mutating the merged database in place is not enough:
      // several layers downstream snapshot it — applyOverrides copies edited records, and the sheet
      // memoises a player-facing copy — so a mutation lands in objects nobody is reading any more and
      // every description stays blank. A rebuild gives the database a new identity, which is what
      // those memos are keyed on.
      const db = cachedCore as unknown as Record<string, Record<string, Record<string, unknown>> | undefined>;
      for (const [bucket, records] of Object.entries(byBucket)) {
        const target = db?.[bucket];
        if (!target) continue;
        for (const [id, v] of Object.entries(records)) {
          const rec = target[id];
          if (!rec) continue;
          if (v.d !== undefined) rec.description = v.d;
          if (v.r !== undefined) rec.descRefs = v.r;
        }
      }
      descriptionsLoaded = true;
      const rebuilt = rebuildContent();
      for (const fn of descListeners) fn(rebuilt);
    } catch (err) {
      // Descriptions are cosmetic relative to the engine: every number still derives without them.
      console.error('Failed to load core-descriptions.json; descriptions will be blank.', err);
    }
  })();
  return descPending;
}

/** Fetch + parse public/core.json once, merged with the seed. Concurrent callers share the
 *  in-flight promise (main.tsx prefetches before React mounts; App awaits the same load). */
export function loadContent(): Promise<ContentDatabase> {
  if (cached) return Promise.resolve(cached);
  pending ??= (async () => {
    try {
      const res = await fetch(`${import.meta.env.BASE_URL}core.json`);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const core = (await res.json()) as Partial<ContentDatabase>;
      cachedCore = core;
      cached = mergeWithSeed(core);
      // Descriptions are 61% of the data and nobody reads one until they open it, so they ship in a
      // SECOND file and fill in a moment later. Deliberately not awaited: the whole point is that the
      // app becomes interactive after parsing ~8 MB instead of 22.5.
      void loadDescriptions();
    } catch (err) {
      // Fall back to the seed alone so the app still boots (and the example
      // character resolves) if the data file is missing or unreadable.
      console.error('Failed to load core.json; falling back to seed content.', err);
      cached = mergeWithSeed({});
    }
    return cached;
  })();
  return pending;
}
